package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: records their due-total now, binds each of their claims that counts to the
 * figure it has now, and unbinds (live again) each that does not. The due-total is their counting claims'
 * figures added up; n/a when their grade has no rate on the sheet's today and no counting claim keeps a figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SheetRepository sheets, Out<Statement> statement, Out<Person> updated) {
        LocalDate today = sheets.today(person.sheetId());
        List<Rate> sheetRates = rates.findAll(person.sheetId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim claim : claims.findForPerson(person.sheetId(), person.id())) {
            if (!claim.counts()) {
                claims.bindStatement(claim, false, null);
                continue;
            }
            boolean fixed = claim.due() != null || (claim.stated() && claim.statedDue() != null);
            BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.grade(), claim.date()));
            claims.bindStatement(claim, true, figure);
            counted++;
            kept |= fixed;
            if (figure != null) {
                total = total.add(figure);
            }
        }
        String dueTotal = Rate.inForce(sheetRates, person.grade(), today) == null && !kept ? "n/a"
                : total.setScale(2).toPlainString();
        statement.set(new Statement(person.name(), dueTotal, counted));
        updated.set(people.recordStatement(person, dueTotal, today));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none, and voiding clears it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one.
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, Integer number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue) {

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, Integer nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue);
    }

    /** Whether the claim counts toward the totals: only OPEN and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to, else its amount at the given live rate (null: none).
     */
    public BigDecimal figure(BigDecimal liveRate) {
        if (due != null) {
            return due;
        }
        return stated ? statedDue : due(amount, liveRate);
    }

    /** An amount times a percent rate, divided by 100, rounded half to even to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(Integer number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, due, opened_by, stated, stated_due";

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
                ClaimRepository::map, sheetId);
    }

    /** The claim with this id on this sheet, or null. */
    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ClaimRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Insert a new claim (null id) or update an existing one; the claim as stored. */
    public Claim save(Claim claim) {
        if (claim.id() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, due = ?, opened_by = ? WHERE id = ? AND sheet_id = ?",
                    claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.status().name(), claim.number(),
                    claim.due(), claim.openedBy(), claim.id(), claim.sheetId());
            return claim;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status) VALUES (?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.sheetId());
            ps.setLong(2, claim.personId());
            ps.setBigDecimal(3, claim.amount());
            ps.setDate(4, Date.valueOf(claim.date()));
            ps.setString(5, claim.note());
            ps.setString(6, claim.status().name());
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), false, null);
    }

    /** The person's claims, newest first. */
    public List<Claim> findForPerson(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
                ClaimRepository::map, sheetId, personId);
    }

    /** Bind the claim to a statement's figure (null: n/a), or unbind it (live again) when not stated. */
    public void bindStatement(Claim claim, boolean stated, BigDecimal statedDue) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ? AND sheet_id = ?",
                stated, stated ? statedDue : null, claim.id(), claim.sheetId());
    }

    private static Claim map(ResultSet rs, int n) throws SQLException {
        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount").setScale(2), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
                ClaimStatus.valueOf(rs.getString("status")), rs.getObject("claim_number", Integer.class),
                rs.getBigDecimal("due"), rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
 * Opening gives the claim the sheet's next number; voiding clears it (the number is not reused).
 * Opening records the user who opened it; that user cannot settle it (four eyes).
 * Settling fixes the claim's due at its person's grade's rate in force on the claim's date — or, when a statement
 * bound the claim, at the figure it was bound to; with no figure it stays live.
 */
public class ApplyClaimAction {
    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim, SheetRepository sheets,
            PersonRepository people, RateRepository rates,
            Out<ClaimAction> applied, Out<ClaimNumber> number, Out<Claim> updated) throws InvalidClaimException {
        ClaimAction found = ClaimAction.of(action);
        if (found == null) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
        if (!found.allowedFrom(claim.status())) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
        }
        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
        }
        Integer next = switch (found) {
            case OPEN -> sheets.nextClaimNumber(claim.sheetId());
            case VOID -> null;
            default -> claim.number();
        };
        applied.set(found);
        number.set(new ClaimNumber(found == ClaimAction.VOID ? claim.number() : next));
        BigDecimal due = found == ClaimAction.SETTLE ? settledDue(claim, people, rates) : claim.due();
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
    }

    private static BigDecimal settledDue(Claim claim, PersonRepository people, RateRepository rates) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        BigDecimal rate = person == null ? null
                : Rate.inForce(rates.findAll(claim.sheetId()), person.grade(), claim.date());
        return Claim.due(claim.amount(), rate);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Records the claim's status change, with its person's name; runs only once the change has been allowed.
 * Settling also records the due it fixed (n/a when the grade had no rate).
 */
public class AuditClaimAction {
    public void audit(@Val ClaimAction action, @Val ClaimNumber number, @Val Claim claim, PersonRepository people,
            @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(action.event() + " sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(number.value())
                + (action == ClaimAction.SETTLE
                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().setScale(2).toPlainString())
                        : ""));
    }
}
package net.officefloor.hq.app.claim;

/** A change of a claim's status: the status it may start from, the status it ends in, and its audit event. */
public enum ClaimAction {
    OPEN("open", ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SETTLE("settle", ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    VOID("void", ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN);

    private final String path;
    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(String path, ClaimStatus to, String event, ClaimStatus... from) {
        this.path = path;
        this.to = to;
        this.event = event;
        this.from = from;
    }

    /** The action named in the path, or null. */
    public static ClaimAction of(String path) {
        for (ClaimAction action : values()) {
            if (action.path.equals(path)) {
                return action;
            }
        }
        return null;
    }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) {
                return true;
            }
        }
        return false;
    }

    public ClaimStatus to() {
        return to;
    }

    public String event() {
        return event;
    }
}
